<?php
namespace Tests\Feature;
use App\Models\{Appointment,AppointmentConfirmation as Link,Company,User};
use App\Services\AppointmentReminder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\{Carbon,Str};
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class ReminderTest extends TestCase {
 use RefreshDatabase;
 private Company $company;private User $owner;private User $professional;private Appointment $appointment;
 protected function setUp():void{parent::setUp();$this->travelTo(Carbon::parse('2026-10-01 12:00:00','UTC'));$this->company=Company::create(['name'=>'Clínica teste','slug'=>'reminder','booking_timezone'=>'America/Sao_Paulo']);$this->owner=$this->user('owner');$this->professional=$this->user('professional');$this->appointment=Appointment::create(['company_id'=>$this->company->id,'professional_id'=>$this->professional->id,'created_by'=>$this->owner->id,'client_name'=>'Nome confidencial','client_phone'=>'(75) 99999-1234','client_email'=>'patient@example.test','service'=>'Procedimento privado','notes'=>'Diagnóstico confidencial','starts_at'=>'2026-10-02 10:00','ends_at'=>'2026-10-02 10:30','status'=>'scheduled']);}
 private function user(string $role,?Company $c=null):User{return User::create(['company_id'=>($c??$this->company)->id,'name'=>'Usuário '.$role,'email'=>Str::uuid().'@example.test','role'=>$role,'password'=>'TestOnly-2026','active'=>true]);}
 private function issue(array $extra=[]):Link{$this->actingAs($this->owner)->post(route('reminders.issue',$this->appointment->id),array_replace(['request_id'=>(string)Str::uuid(),'acknowledge'=>'1'],$extra))->assertSessionHasNoErrors();return Link::latest('id')->first();}
 private function url(Link $link):string{return route('confirmation.show',$link->token);}
 private function form():array{return ['professional_id'=>$this->professional->id,'client_name'=>$this->appointment->client_name,'client_phone'=>$this->appointment->client_phone,'client_email'=>$this->appointment->client_email,'service'=>$this->appointment->service,'starts_at'=>'2026-10-02T10:00','ends_at'=>'2026-10-02T10:30','status'=>'scheduled','notes'=>''];}
 public function test_link_random_encrypted_expiry_and_get_is_read_only():void{$link=$this->issue();$this->assertSame(64,strlen($link->token));$this->assertSame(hash('sha256',$link->token),$link->token_hash);$this->assertStringNotContainsString($link->token,DB::table('appointment_confirmations')->value('token'));$this->assertSame('2026-10-02 13:00:00',$link->expires_at->format('Y-m-d H:i:s'));$this->get($this->url($link))->assertOk()->assertHeader('Cache-Control','no-store, private')->assertHeader('Referrer-Policy','no-referrer')->assertHeader('X-Robots-Tag','noindex, nofollow, nosnippet')->assertSee('02/10/2026')->assertDontSee('Nome confidencial')->assertDontSee('Procedimento privado')->assertDontSee('Diagnóstico confidencial')->assertDontSee('patient@example.test');$this->assertSame('scheduled',$this->appointment->fresh()->status);$this->assertNull($link->fresh()->response);}
 public function test_confirm_then_cancel_retries_do_not_reactivate():void{$l=$this->issue();$this->post($this->url($l),['choice'=>'confirmed','acknowledge'=>'1'])->assertRedirect();$this->post($this->url($l),['choice'=>'confirmed','acknowledge'=>'1'])->assertRedirect();$this->assertSame('confirmed',$this->appointment->fresh()->status);$this->assertSame('Confirmado pelo paciente',$this->appointment->fresh()->responseLabel());$this->post($this->url($l),['choice'=>'cancelled','acknowledge'=>'1'])->assertRedirect();$this->assertSame('cancelled',$this->appointment->fresh()->status);$this->post($this->url($l),['choice'=>'cancelled','acknowledge'=>'1'])->assertRedirect();$this->post($this->url($l),['choice'=>'confirmed','acknowledge'=>'1'])->assertStatus(410);$this->get($this->url($l))->assertOk()->assertSee('Agendamento cancelado');}
 public function test_requires_acknowledgement_and_rejects_unknown_choice_and_token():void{$l=$this->issue();$this->post($this->url($l),['choice'=>'confirmed'])->assertSessionHasErrors('acknowledge');$this->post($this->url($l),['choice'=>'completed','acknowledge'=>'1'])->assertSessionHasErrors('choice');$this->get(route('confirmation.show',str_repeat('a',64)))->assertNotFound();$this->assertSame('scheduled',$this->appointment->fresh()->status);}
 public function test_generation_retry_existing_link_rotation_and_revocation():void{$form=['request_id'=>(string)Str::uuid(),'acknowledge'=>'1'];$a=$this->issue($form);$this->issue($form);$this->issue();$this->assertDatabaseCount('appointment_confirmations',1);$b=$this->issue(['renew'=>'1']);$this->assertDatabaseCount('appointment_confirmations',2);$this->get($this->url($a))->assertStatus(410);$this->get($this->url($b))->assertOk();$this->post(route('reminders.revoke',$this->appointment->id),['link_id'=>$b->id])->assertSessionHasNoErrors();$this->get($this->url($b))->assertStatus(410);$this->assertSame('scheduled',$this->appointment->fresh()->status);}
 public function test_rescheduling_resets_confirmation_and_revokes_old_links():void{$l=$this->issue();$this->post($this->url($l),['choice'=>'confirmed','acknowledge'=>'1']);$form=$this->form();$form['starts_at']='2026-10-02T11:00';$form['ends_at']='2026-10-02T11:30';$form['status']='confirmed';$this->put(route('appointments.update',$this->appointment->id),$form)->assertSessionHasNoErrors();$this->assertSame('scheduled',$this->appointment->fresh()->status);$this->get($this->url($l))->assertStatus(410);$this->post($this->url($l),['choice'=>'cancelled','acknowledge'=>'1'])->assertStatus(410);}
 public function test_contact_change_and_internal_status_change_invalidate_but_notes_do_not():void{$l=$this->issue();$form=$this->form();$form['notes']='Nota administrativa';$this->put(route('appointments.update',$this->appointment->id),$form)->assertSessionHasNoErrors();$this->get($this->url($l))->assertOk();$form['client_phone']='75988887777';$this->put(route('appointments.update',$this->appointment->id),$form)->assertSessionHasNoErrors();$this->get($this->url($l))->assertStatus(410);$l=$this->issue();$form['status']='cancelled';$this->put(route('appointments.update',$this->appointment->id),$form)->assertSessionHasNoErrors();$this->get($this->url($l))->assertStatus(410);}
 public function test_expiration_inactive_and_timezone_change_are_blocked():void{$l=$this->issue();$this->travelTo(Carbon::parse('2026-10-02 13:00:00','UTC'));$this->get($this->url($l))->assertStatus(410);$this->post($this->url($l),['choice'=>'confirmed','acknowledge'=>'1'])->assertStatus(410);$this->travelTo(Carbon::parse('2026-10-01 12:00:00','UTC'));$this->company->update(['active'=>false]);$this->get($this->url($l))->assertStatus(410);$this->company->update(['active'=>true,'booking_timezone'=>'America/Manaus']);$this->get($this->url($l))->assertStatus(410);}
 public function test_scope_isolation_for_other_company_and_other_professional():void{$l=$this->issue();$other=Company::create(['name'=>'Outra','slug'=>'outra-reminder']);foreach([$this->user('owner',$other),$this->user('professional')] as $u){$this->flushSession();$this->actingAs($u);$this->get(route('reminders.show',$this->appointment->id))->assertNotFound();$this->post(route('reminders.issue',$this->appointment->id),['request_id'=>(string)Str::uuid(),'acknowledge'=>'1'])->assertNotFound();$this->post(route('reminders.revoke',$this->appointment->id),['link_id'=>$l->id])->assertNotFound();$this->post(route('reminders.sent',$this->appointment->id),['link_id'=>$l->id,'acknowledge'=>'1'])->assertNotFound();$this->get(route('reminders.index',['from'=>'2026-10-01','to'=>'2026-10-03']))->assertOk()->assertDontSee('Nome confidencial');}}
 public function test_manual_sent_mark_is_separate_from_issuing_and_public_view():void{$l=$this->issue();$this->get(route('reminders.show',$this->appointment->id))->assertOk()->assertSee('https://wa.me/5575999991234',false);$this->get($this->url($l));$this->assertNull($l->fresh()->sent_at);$this->post(route('reminders.sent',$this->appointment->id),['link_id'=>$l->id,'acknowledge'=>'1'])->assertSessionHasNoErrors();$this->assertSame($this->owner->id,$l->fresh()->sent_by);$this->assertNull($l->fresh()->response);}
 public function test_phone_normalization_and_no_clinical_content_in_message():void{$s=app(AppointmentReminder::class);$this->assertSame('5575999991234',$s->phone('(75) 99999-1234'));$this->assertSame('5575999991234',$s->phone('55 75 99999-1234'));$this->assertSame('351912345678',$s->phone('+351 912345678'));$this->assertNull($s->phone('75999991234 ramal 2'));$this->assertNull($s->phone('123'));$m=$s->message($this->appointment,$this->issue());$this->assertStringNotContainsString('Nome confidencial',$m);$this->assertStringNotContainsString('Procedimento privado',$m);$this->assertStringContainsString('02/10/2026',$m);}
 public function test_deletion_and_completed_state_cannot_be_changed_with_old_link():void{$l=$this->issue();$this->appointment->update(['status'=>'completed']);$this->get($this->url($l))->assertStatus(410);$this->appointment->delete();$this->assertDatabaseCount('appointment_confirmations',0);$this->get($this->url($l))->assertNotFound();}
}
